using System.Buffers.Binary;
using IMRCRaceControl.Core;
using IMRCRaceControl.Models;
using IMRCRaceControl.Services;

static class DecoderChecks
{
    public static async Task<int> Run()
    {
        var count = 0;
        void Check(bool value, string label) { if (!value) throw new Exception(label); count++; }
        // Independently captured RC4 and status records, not generated by the
        // implementation under test. Provenance: docs/DECODER_P3.md.
        var frame = Convert.FromHexString("8E023300CF02000001000104B29B0100030427FC70000408E819E6BD8A7504000502330006021000080200008104FC0504008F");
        var status = Convert.FromHexString("8E021F00D6870000020001021A00070228000C01780601008104930F02008F");
        var now = new DateTimeOffset(2026, 10, 3, 20, 0, 0, TimeSpan.Zero);
        var parser = new P3StreamDecoder();
        var decoded = parser.Feed(frame, now).Passings.Single();
        Check(decoded.TransponderId == "7404583", "Real RC4 transponder decoded without a driver registry");
        Check(decoded.DecoderId == 0x405fc && decoded.PassingNumber == 0x19bb2, "Real decoder/passing identity");
        Check(decoded.ClockMicroseconds == 0x4758abde619e8 && decoded.Hits == 16 && decoded.Strength == 51, "Real clock and signal metadata");
        Check(decoded.Timestamp == now, "Unset/old decoder date anchored to local receipt");
        Check(parser.Feed(status, now).Passings.Count == 0, "Status never becomes a transponder");
        Check(parser.Feed(status, now).Summary.Contains("status"), "Status is diagnosed accurately");
        Check(parser.Feed(frame, now.AddSeconds(1)).Passings.Count == 0, "Duplicate passing suppressed");
        parser.ResetConnection();
        Check(parser.Feed(frame, now.AddSeconds(2)).Passings.Count == 0, "Replay after reconnect suppressed");
        for (var split = 1; split < frame.Length; split++)
        {
            var partial = new P3StreamDecoder();
            Check(partial.Feed(frame.AsSpan(0, split), now).Passings.Count == 0, $"No premature ID at split {split}");
            Check(partial.Feed(frame.AsSpan(split), now).Passings.Single().TransponderId == "7404583", $"Split {split} decoded");
        }
        var next = (byte[])frame.Clone();
        BinaryPrimitives.WriteUInt32LittleEndian(next.AsSpan(12), decoded.PassingNumber + 1);
        BinaryPrimitives.WriteUInt64LittleEndian(next.AsSpan(24), decoded.ClockMicroseconds + 4_339_000);
        var nextWire = Encode(next);
        var combined = new P3StreamDecoder().Feed(status.Concat(frame).Concat(nextWire).ToArray(), now).Passings;
        Check(combined.Count == 2, "Coalesced status and two passings");
        Check(combined[1].Timestamp - combined[0].Timestamp == TimeSpan.FromMilliseconds(4339), "Decoder lap interval preserved independent of transport batching");
        var escaped = (byte[])next.Clone();
        BinaryPrimitives.WriteUInt32LittleEndian(escaped.AsSpan(18), 0x8f8e8d);
        var escapedWire = Encode(escaped);
        var byteReader = new P3StreamDecoder();
        var bytePassings = new List<DecoderPassing>();
        foreach (var value in escapedWire) bytePassings.AddRange(byteReader.Feed(new[] { value }, now).Passings);
        Check(bytePassings.Single().TransponderId == ((uint)0x8f8e8d).ToString(), "Escaped bytes and split escape pairs");
        var corrupt = (byte[])frame.Clone(); corrupt[18] ^= 1;
        Check(new P3StreamDecoder().Feed(corrupt, now).Passings.Count == 0, "Corrupt checksum cannot manufacture an ID");
        var length = (byte[])frame.Clone(); length[2]--;
        Check(new P3StreamDecoder().Feed(Encode(length), now).Passings.Count == 0, "Incorrect declared length rejected");
        var field = (byte[])frame.Clone(); field[17] = 250;
        Check(new P3StreamDecoder().Feed(Encode(field), now).Passings.Count == 0, "Out-of-bounds TLV rejected");
        var zero = (byte[])frame.Clone(); zero.AsSpan(18, 4).Clear();
        Check(new P3StreamDecoder().Feed(Encode(zero), now).Passings.Count == 0, "Zero tag rejected");
        var missing = (byte[])frame.Clone(); missing[16] = 0x79;
        Check(new P3StreamDecoder().Feed(Encode(missing), now).Passings.Count == 0, "Missing transponder rejected");
        var unknownField = (byte[])frame.Clone(); unknownField[32] = 0x79;
        Check(new P3StreamDecoder().Feed(Encode(unknownField), now).Passings.Count == 1, "Unknown optional TLV skipped");
        var version = (byte[])frame.Clone(); version[1] = 3;
        Check(new P3StreamDecoder().Feed(Encode(version), now).Passings.Count == 0, "Unsupported version is not guessed");
        var recovery = new P3StreamDecoder();
        var junk = new byte[] { 4, 9, 0x8e, 2, 0x8d, 0 };
        Check(recovery.Feed(junk.Concat(corrupt).Concat(frame).ToArray(), now).Passings.Count == 1, "Resynchronizes after noise, malformed escape and bad CRC");
        recovery.ResetConnection(); recovery.Feed(frame.AsSpan(0, 24), now); recovery.ResetConnection();
        Check(recovery.Feed(frame.AsSpan(24), now).Passings.Count == 0, "Partial record never crosses connections");
        var oversized = new byte[70000]; oversized[0] = 0x8e;
        Check(new P3StreamDecoder().Feed(oversized.Concat(frame).ToArray(), now).Passings.Count == 1, "Bounded incomplete frame recovers");
        var observer = new DetectedTransponder { TransponderId = decoded.TransponderId };
        observer.Observe(now, "LAN", null, decoded.Hits, decoded.Strength);
        Check(observer.DriverName == "Unassigned" && observer.TransponderId == "7404583", "Unregistered ID remains visible and copyable");
        observer.Observe(now.AddSeconds(4), "LAN", "Yoshi", 17, 60);
        Check(observer.Crossings == 2 && observer.DriverName == "Yoshi", "Reader row updates without adding another row per lap");
        var packets = new List<DecoderIngressService.FormattedPacket>();
        await using (var ingress = new DecoderIngressService())
        {
            ingress.PacketFormatted += packet => packets.Add(packet);
            ingress.Enqueue("LAN", frame[..20], now);
            ingress.Enqueue("LAN", frame[20..], now);
            ingress.Enqueue("LAN", status, now);
            ingress.ResetConnection();
            ingress.Enqueue("LAN", frame, now);
        }
        Check(packets.Count == 4, "Ingress reset is not a fake traffic chunk");
        Check(packets.SelectMany(p => p.Passings).Count() == 1, "Ordered ingress routes parsed passing once");
        Check(packets[0].Hex == Convert.ToHexString(frame[..20]), "Original raw traffic remains intact");
        return count;
    }

    private static byte[] Encode(byte[] raw)
    {
        // Independent table CRC encoder for synthetic edge cases.
        var data = (byte[])raw.Clone(); data[4] = data[5] = 0;
        var table = new ushort[256];
        for (var n = 0; n < table.Length; n++)
        {
            var value = n << 8;
            for (var bit = 0; bit < 8; bit++) value = ((value << 1) ^ ((value & 0x8000) == 0 ? 0 : 0x1021)) & 0xffff;
            table[n] = (ushort)value;
        }
        ushort crc = 0xffff;
        foreach (var value in data) crc = (ushort)(table[crc >> 8] ^ (crc << 8) ^ value);
        BinaryPrimitives.WriteUInt16LittleEndian(data.AsSpan(4), crc);
        var wire = new List<byte> { 0x8e };
        foreach (var value in data.AsSpan(1, data.Length - 2))
        {
            if (value is >= 0x8d and <= 0x8f) { wire.Add(0x8d); wire.Add((byte)(value + 0x20)); }
            else wire.Add(value);
        }
        wire.Add(0x8f); return wire.ToArray();
    }
}
